"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["6513"],{59415(e){e.exports=JSON.parse('{"id":"FIN-072","slug":"overdraft-protection","term":"Overdraft Protection","also_known_as":[],"difficulty":"Beginner","definition":"Overdraft protection is a bank service that covers a payment when your account does not have enough money, instead of rejecting it, usually in return for a fee or interest.","explanation":["Without overdraft protection, a payment that exceeds your balance might be declined, which could mean a missed bill or an embarrassing card rejection. With it, the bank allows the payment to go through.","Overdraft protection can work in different ways. The bank might lend you the shortfall directly, as an overdraft, and charge a fee or interest. It might move money automatically from a linked savings account or credit card to cover the gap. Moving money from your own savings account is often the cheapest option, though there may still be a small transfer fee.","The convenience comes at a cost. Some banks charge a flat fee each time protection is used, which can be expensive if several small purchases go through while the account is overdrawn. Three purchases of 5, each triggering a fee of 25, could cost 75 in fees for 15 of spending.","Overdraft protection is useful as a backstop, but it works best alongside careful tracking of your balance. Reading the bank\'s fee schedule and choosing the cheapest form of protection can save a lot of money."],"note":"","total":1500,"prev":{"slug":"overdraft","term":"Overdraft"},"next":{"slug":"overfitting","term":"Overfitting"}}')}}]);